import React, { useEffect, useState } from "react";

import api from "../services/api";

const BookingForm = ({
  formData,
  onChange,
  onSubmit,
  onAvailabilityCheck,
  loading
}) => {
  const [blockId, setBlockId] = useState(formData.blockId || "");
  const [blocks, setBlocks] = useState([]);
  const [resources, setResources] = useState([]);
  const [blocksLoading, setBlocksLoading] = useState(false);
  const [resourceLoading, setResourceLoading] = useState(false);

  useEffect(() => {
    setBlockId(formData.blockId || "");
  }, [formData.blockId]);

  useEffect(() => {
    let ignore = false;

    const fetchBlocks = async () => {
      setBlocksLoading(true);

      try {
        const response = await api.get("/blocks");
        if (!ignore) {
          setBlocks(response.data || []);
        }
      } catch (error) {
        console.log("Failed to load blocks", error);
        if (!ignore) {
          setBlocks([]);
        }
      } finally {
        if (!ignore) {
          setBlocksLoading(false);
        }
      }
    };

    fetchBlocks();

    return () => {
      ignore = true;
    };
  }, []);

  useEffect(() => {
    let ignore = false;

    const fetchResources = async () => {
      if (!blockId) {
        setResources([]);
        setResourceLoading(false);
        return;
      }

      setResourceLoading(true);

      try {
        const response = await api.get(`/blocks/${blockId}/resources`);
        if (!ignore) {
          setResources(response.data || []);
        }
      } catch (error) {
        console.log("Failed to load resources", error);
        if (!ignore) {
          setResources([]);
        }
      } finally {
        if (!ignore) {
          setResourceLoading(false);
        }
      }
    };

    fetchResources();

    return () => {
      ignore = true;
    };
  }, [blockId]);

  const handleBlockChange = (event) => {
    const nextBlockId = event.target.value;

    setBlockId(nextBlockId);
    onChange({
      target: {
        name: "blockId",
        value: nextBlockId
      }
    });
  };

  return (
    <div className="panel-card">
      <div className="panel-header">
        <div>
          <h3>Create Booking</h3>
          <p>Choose a block, resource, date, and time slot.</p>
        </div>
      </div>

      <form className="grid-form" onSubmit={onSubmit}>
        <label>
          <span>Block</span>
          <select name="blockId" value={blockId} onChange={handleBlockChange} required>
            <option value="">{blocksLoading ? "Loading blocks..." : "Select block"}</option>
            {blocks.map((block) => (
              <option key={block.id} value={block.id}>
                Block {block.name}
              </option>
            ))}
          </select>
        </label>

        <label>
          <span>Resource</span>
          <select
            name="resourceId"
            value={formData.resourceId}
            onChange={onChange}
            required
            disabled={!blockId || resourceLoading}
          >
            <option value="">{resourceLoading ? "Loading..." : "Select resource"}</option>
            {resources.map((resource) => (
              <option key={resource.id} value={resource.id}>
                {resource.name}
              </option>
            ))}
          </select>
        </label>

        <label>
          <span>Date</span>
          <input type="date" name="bookingDate" value={formData.bookingDate} onChange={onChange} required />
        </label>

        <label>
          <span>Start time</span>
          <input type="time" name="startTime" value={formData.startTime} onChange={onChange} required />
        </label>

        <label>
          <span>End time</span>
          <input type="time" name="endTime" value={formData.endTime} onChange={onChange} required />
        </label>

        <label className="full-width">
          <span>Purpose</span>
          <textarea
            name="purpose"
            value={formData.purpose}
            onChange={onChange}
            rows="4"
            placeholder="Add purpose for this booking"
          />
        </label>

        <div className="form-actions full-width">
          <button type="button" className="secondary-button" onClick={onAvailabilityCheck}>
            Check Availability
          </button>
          <button type="submit" className="primary-button" disabled={loading}>
            {loading ? "Submitting..." : "Create Booking"}
          </button>
        </div>
      </form>
    </div>
  );
};

export default BookingForm;
